Q: Detect whether Date &amp; Time is set automatically or manually in Flutter A: <p>If you have a endpoint that returns the utc time then you can simply do that by comparing the deviceUtc vs the actualUTC, You can use this free service to get the actual time in UTC <a href="https://timeapi.io/swagger/index.html" rel="nofollow noreferrer">https://timeapi.io/swagger/index.html</a></p>
<p>drift = deviceUTC - serverUtc</p>
<pre class="lang-dart prettyprint-override"><code>Future&lt;bool&gt; isDeviceTimeChangedFromServerTime({
  required String? authToken,
  Duration tolerance = kDefaultDateChangeTolerance,
}) async {
  if (authToken == null || authToken.isEmpty) {
    return false;
  }

  try {
    final response = await http
        .get(
          Uri.parse(Constants.serverTimeUrl),
        )
        .timeout(const Duration(seconds: 15));
    if (response.statusCode != 200) {
      return false;
    }

    final body = jsonDecode(response.body) as Map&lt;String, dynamic&gt;?;
    final serverTimeUtcZ = body?['utc_time'];
    if (serverTimeUtcZ == null) {
      return false;
    }
    final serverTimeUtc = DateTime.parse(serverTimeUtcZ);
    final deviceUtc = DateTime.now().toUtc();
    final currentOffset = (deviceUtc.difference(serverTimeUtc).inSeconds).abs();
    if (currentOffset &gt; tolerance.inSeconds) {
      return true;
    }
    return false;
  } catch (e) {
    return false;
  }
}
</code></pre>
